<script setup lang="ts">
const db=useSupabaseClient(),route=useRoute(),busy=ref(true),error=ref(''),rows=ref<any[]>([]),schoolName=ref('')
onMounted(async()=>{const {data:{user}}=await db.auth.getUser();if(!user){await navigateTo('/login');return}const r=await db.from('school_memberships').select('school_id,role,schools(name)').eq('user_id',user.id);if(r.error){error.value=r.error.message;busy.value=false;return}const id=typeof route.query.school==='string'?route.query.school:'';const m=(r.data||[]).find(x=>x.school_id===id&&['school_admin','teacher'].includes(x.role));if(!m){error.value='You do not have access to this school.';busy.value=false;return}schoolName.value=(m.schools as any)?.name||'School';const s=await db.from('students').select('id,student_number,given_name,family_name').eq('school_id',id).order('family_name').limit(500);rows.value=s.data||[];error.value=s.error?.message||'';busy.value=false})
</script>
<template><div class="page"><div class="shell admin-section"><NuxtLink to="/school/dashboard">← School Dashboard</NuxtLink><h1>{{schoolName}} — Students</h1><p class="notice">School-scoped, read-only student directory. Dates of birth are not displayed.</p><p v-if="busy">Loading…</p><p v-if="error" class="error" role="alert">{{error}}</p><div v-if="!busy&&!error" class="card"><h2>Students ({{rows.length}}{{rows.length===500?'+':''}})</h2><div v-for="s in rows" :key="s.id" class="data-row"><span>{{s.family_name}}, {{s.given_name}}</span><small>{{s.student_number}}</small></div><p v-if="!rows.length">No students found.</p></div></div></div></template>
